from research_helpers import source, assessment, record, scope, evidence, decision, write_batch

refs=[
 ('rapture','Rapture','BioShock Wiki contributors','https://bioshock.fandom.com/wiki/Rapture','Pre-collapse Rapture has employed builders, mechanics, investment and an active market; the Thinker controls infrastructure.','Fan-made RaptureReborn MMORPG economy pages were discarded; automatic infrastructure does not prove wages ceased allocating necessities.'),
 ('lamb','BioShock 2 plot','Wikipedia contributors','https://en.wikipedia.org/wiki/BioShock_2','Lamb plans to concentrate residents’ memories in a selfless leader; the player disrupts her project.','A proposed utopian person is not an implemented collective material economy; fan villain-ranking commentary was not used.'),
 ('finkton','Finkton','BioShock Wiki contributors','https://bioshock.fandom.com/wiki/Finkton','Human workers face low wages, long hours, poor housing and hunger while factories make advanced automata.','Biological/cyborg labor and vending machines do not prove unnecessary employment or general labor-independent access.'),
 ('citadel','Citadel Station','System Shock Wiki contributors','https://shodan.fandom.com/wiki/Citadel_Station','Crew perform repairs and resist SHODAN’s access restrictions, radiation and biological attacks.','A captured workplace with cyborg patrols is not automatically a supported human post-work society; remake distinctions remain explicit.'),
 ('wau','WAU','SOMA Wiki contributors','https://soma.fandom.com/wiki/WAU','The station system preserves bodies in altered/trance states and copies human scans into machines.','Mixed preservation, active copies and damaged bodies require distinct population/access evidence; preservation alone is not a leisure census.'),
 ('ark','ARK','SOMA Wiki contributors','https://soma.fandom.com/wiki/ARK','The launched ARK supports active copied human minds in a simulation; solar power is designed for a very long autonomous duration.','The predicted millennial lifespan is a design claim, not an elapsed observed history; control/governance is not fully specified.'),
 ('soma-plot','SOMA plot','Wikipedia contributors','https://en.wikipedia.org/wiki/Soma_(video_game)','The post-credits scene depicts the ARK copies of Simon and Catherine together in a functioning simulated environment after successful launch.','Copies do not transfer or erase their earlier selves; the abandoned versions do not share the ARK’s resource access.'),
 ('elohim','Elohim','The Talos Principle Wiki contributors','https://taloswiki.org/wiki/Elohim','The simulation tests artificial persons’ reasoning and independence for embodied succession to extinct humans.','An implemented training/test system is not automatically a resident post-work economy; human-successor claims do not supply resource institutions.'),
 ('talos2','The Talos Principle 2 plot','Wikipedia contributors','https://en.wikipedia.org/wiki/The_Talos_Principle_2','Artificial successors build New Jerusalem through resource collection; the discovered singularity fabricates matter; endings alter its use and leadership.','Technology and branch choices do not specify universal household access. The DLC vacation and recovery stories are not a complete material constitution.'),
 ('talos-scarcity','The Talos Principle II review','Relaxing Gameplaid reviewer','https://relaxing-gameplaid.net/en/the-talos-principle-2/','The review discusses New Jerusalem’s energy and body-material scarcity and useful engineering work.','Secondary commentary, not an exact census or proof of post-scarcity distribution.'),
 ('nier','NieR:Automata plot','Wikipedia contributors','https://en.wikipedia.org/wiki/Nier:_Automata','Android forces and independent machines fight, repair and investigate; humans are extinct and their genetic archive is not an awake population.','The game’s Machine Network, resistance and Pascal village are distinct groups; no anime economic equivalence is assumed.'),
 ('machines','Machines in NieR:Automata','Wikipedia contributors','https://en.wikipedia.org/wiki/Machines_%28Nier%3A_Automata%29','Sentient alien-created machines imitate human institutions and retain war to promote evolution.','Sentience and imitation are not in themselves a supported human-person population or automatic allocation regime.')
]
S=[source('src-b75-'+sid,title,author,url,'game_lore_reference','Short reference plot, specifications or criticism passage',claim,limits) for sid,title,author,url,claim,limits in refs]
a=['src-b75-ark','src-b75-soma-plot']
R=[record('soma-ark-active-human-copies','c0598','SOMA — The launched ARK community','SOMA','Active human-derived minds in the solar-powered ARK',['game'],
 scope('SOMA released game','Successful launch and its functioning post-credits simulation','Active copies of human minds on the ARK, an explicit human-derived person proxy',['The original biological bodies','Simon and Catherine versions left on PATHOS-II','Dormant scan files as additional residents','An already observed thousands-year future'],proxy=True),
 'The ARK successfully leaves Earth carrying active copies of human minds into a functioning simulated environment. Solar-powered computation supplies their embodied experience without a continuing outside human workforce or current resident wages. The design aims at very long autonomous survival, which supports a fairly strong material guarantee within this closed unit. That duration remains an engineering expectation rather than a demonstrated millennial history, and hardware failure or finite energy reserves still bound the promise.\n\nThe checked references do not explain how residents govern the platform or control its productive substrate. Catherine created it, but authorship alone does not establish either her permanent dictatorship, equal resident ownership or an independent AI sovereign. Control therefore remains unresolved, with a provisional concentrated-provision label. The scoped population consists of active human-derived copies; earlier selves left behind and inactive scan files are separate. The peaceful post-credits encounter is not a participation census, and useful care, research or creation could continue. The nonworking axis remains null rather than treating a virtual paradise as proof that nobody works.',
 {'guarantees':-0.65,'control':None,'nonworking':None},
 {'guarantees':assessment(-0.65,[-0.9,0.25],'low','The simulation works after launch and is designed for autonomous solar-powered continuity; duration, repair and enforceable rights remain uncertain.',a),
  'control':assessment(None,None,'low','Creation and presentation choices do not establish effective platform governance or independent AI authority.',a),
  'nonworking':assessment(None,None,'low','A recreational setting and continuing automatic substrate do not census all active residents’ useful activity.',a)},
 1,a,[evidence('Launched solar-powered computation supports active human-derived minds in an operating simulation.',a,'ARK specifications/history and released post-credits scene','secondary_reference_to_depicted_events_and_design')],
 ['Active human-derived proxy, excluding inactive files and abandoned versions.', 'Projected lifespan is not elapsed history.', 'Governance and participation remain unresolved.', 'Physical escape occurs for the copies; continuity of the earlier selves is not assumed.'],alternatives=[2,5])]
rows=[
 ('c0593','needs_evidence',['rapture'],'Rapture’s advanced infrastructure does not establish ordinary access independent of useful human labor.','Actual builders, mechanics and market income remain central in the short account; a fan-made MMORPG safety net is not canon.'),
 ('c0594','boundary_case',['lamb'],'Lamb’s proposed selfless collective leader is not an implemented post-work economy.','Memory concentration and utopian language do not supply an actual automatic production/allocation arrangement.'),
 ('c0595','boundary_case',['finkton'],'Columbia’s human workers perform real industrial work under harsh wage conditions.','Advanced automata do not prove those jobs are unnecessary or deliberately retained despite full replacement capacity.'),
 ('c0596','boundary_case',['citadel'],'SHODAN’s captured station is a failing workplace and violent conversion project.','Human repair work, restricted access and attacks do not establish a continuing supported resident post-work order.'),
 ('c0597','needs_evidence',['wau','soma-plot'],'WAU’s mixed preservation systems do not establish one coherent active population’s resource arrangement.','Trance-like bodies, active human copies and a terminally supported survivor are different cases; no whole-station leisure or uniform guarantee is inferred.'),
 ('c0599','boundary_case',['elohim'],'Elohim’s simulation is an active testing/training system, not a verified resident post-work economy.','Programs solve real independence tests; an artificial-human succession project does not itself establish durable ordinary provision and participation.'),
 ('c0600','needs_evidence',['talos2','talos-scarcity'],'New Jerusalem’s artificial-human community retains resource scarcity and necessary productive work.','Its human-successor status is explicit, but that does not establish automatic work-independent access to body materials, repair and energy.'),
 ('c0601','needs_evidence',['talos2'],'Matter creation and the choice to use the Machine do not establish the resulting population’s distribution rules.','Real technology and mutually different leadership/ending branches are acknowledged; no universal floor or common productive ownership is invented.'),
 ('c0602','boundary_case',['nier'],'YoRHa and Resistance members perform actual military, maintenance and support work after biological human extinction.','A Moon genetic archive is not a nonworking human population, and artificial military service is not automatically post-work provision.'),
 ('c0603','needs_evidence',['machines','nier'],'The Machine Network’s sentient civilization lacks a verified ordinary resource floor and applicable participation scope.','Continuing war and evolution are real activities; neither robot bodies nor imitation of human institutions supplies a post-work allocation constitution.'),
 ('c0604','needs_evidence',['nier'],'Pascal’s pacifist village does not have a verified work-independent material access system in the short reference.','Peaceful intentions and machine personhood do not settle resource production, repairs or guarantees; a game mod and a denied wiki page were not evidence.')
]
D=[decision(cid,status,reason,['src-b75-'+s for s in ss],analysis=analysis,follow_up='Save the bounded evidence gap/comparison and continue; no full game-lore reconstruction to rescue the lead.') for cid,status,ss,reason,analysis in rows]
D.append(decision('c0598','included','The released ending depicts active human-derived copies supported by an actually launched autonomous computation unit.',a,society_id=R[0]['id']))
D.sort(key=lambda x:x['candidate_id'])
write_batch(75,[f'c{i:04}' for i in range(593,605)],S,R,D,[
 'Twelve fast dispositions and one active ARK community; no full game transcript or lore archive read.',
 'ARK design longevity is distinguished from observed events, and copying does not transfer the abandoned original versions.',
 'Talos artificial persons are recognized as a human-succession project, but philosophical personhood and matter technology do not settle material entitlements.',
 'RaptureReborn fan economics, NieR mods, unofficial copied plot pages and villain rankings were discarded. Failed Fandom opens were respected.',
 'Useful machine-person work is not erased, and genetic archives are not living leisure populations.'
])
